/**
 * @description Tests for the IH_SampleInboundHandler template: missing subject, created record, refused record.
 */
@IsTest
private class IH_SampleInboundHandlerTest {

    private static final String USER_DOMAIN = '@ihsampleinbound.example.com';

    @TestSetup
    static void setup() {
        List<Profile> profiles = [SELECT Id FROM Profile WHERE Name = 'Standard User' WITH SYSTEM_MODE LIMIT 1];
        Id profileId = profiles.isEmpty() ? UserInfo.getProfileId() : profiles[0].Id;
        String unique = EncodingUtil.convertToHex(Crypto.generateAesKey(128)).left(10);
        User tester = new User(LastName = 'IH Sample Tester', Alias = unique.left(8), Email = unique + '@example.com',
            Username = unique + '.inbound' + USER_DOMAIN, ProfileId = profileId, EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US', LocaleSidKey = 'en_US', TimeZoneSidKey = 'America/Chicago');
        System.runAs(new User(Id = UserInfo.getUserId())) {
            insert tester;
        }
    }

    private static User tester() {
        String pattern = '%.inbound' + USER_DOMAIN;
        return [SELECT Id FROM User WHERE Username LIKE :pattern WITH SYSTEM_MODE LIMIT 1];
    }

    private static IntegrationHub.InboundContext call(Map<String, Object> data) {
        IntegrationHub.InboundContext ctx = new IntegrationHub.InboundContext();
        ctx.eventKey = 'SAMPLE_INBOUND';
        ctx.data = data;
        return ctx;
    }

    @IsTest
    static void subjectIsRequired() {
        System.runAs(tester()) {
            IH_SampleInboundHandler handler = new IH_SampleInboundHandler();
            Assert.areEqual(400, handler.handle(call(null)).statusCode, 'no body answers 400');
            Assert.areEqual(400, handler.handle((IntegrationHub.InboundContext) null).statusCode, 'no call answers 400');
            Assert.areEqual(400, handler.handle(call(new Map<String, Object>{ 'subject' => ' ' })).statusCode, 'a blank subject answers 400');
        }
    }

    @IsTest
    static void createsTheRecordOrExplainsWhy() {
        System.runAs(tester()) {
            Test.startTest();
            IntegrationHub.InboundResult result = new IH_SampleInboundHandler().handle(call(new Map<String, Object>{
                'subject' => 'Broken device', 'description' => 'From the sample test' }));
            Test.stopTest();
            if (result.success) {
                Assert.areEqual(Case.SObjectType, result.recordId.getSObjectType(), 'a Case is created and linked');
            } else {
                Assert.areEqual(422, result.statusCode, 'a record the org refuses answers 422');
                Assert.isTrue(result.message.startsWith('Not created'), 'the reason is returned');
            }
        }
    }

    @IsTest
    static void readsTextValues() {
        System.runAs(tester()) {
            Assert.isNull(IH_SampleInboundHandler.text(null, 'subject'), 'no body gives null');
            Assert.areEqual('5', IH_SampleInboundHandler.text(new Map<String, Object>{ 'n' => 5 }, 'n'), 'numbers become text');
        }
    }
}
